{"code":"def transform(grid):
    H=len(grid); W=len(grid[0]); seen=set(); comps=[]
    for r in range(H):
      for c in range(W):
        if grid[r][c] and (r,c) not in seen:
          st=[(r,c)]; seen.add((r,c)); cells=[]
          while st:
            x,y=st.pop(); cells.append((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=x+dx,y+dy
              if 0<=a<H and 0<=b<W and grid[a][b] and (a,b) not in seen:
                seen.add((a,b)); st.append((a,b))
          if len(cells)>=2: comps.append(cells)
    # select the leftmost among the lowest objects
    m=max(sum(x for x,y in q)/len(q) for q in comps)
    cand=[q for q in comps if sum(x for x,y in q)/len(q)>=m-1]
    q=min(cand,key=lambda z:sum(y for x,y in z)/len(z))
    r0=min(x for x,y in q); r1=max(x for x,y in q); c0=min(y for x,y in q); c1=max(y for x,y in q)
    return [row[c0:c1+1] for row in grid[r0:r1+1]]"}

