{"code":"def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c] and (r,c) not in seen:
        st=[(r,c)]; seen.add((r,c)); cells=[]
        while st:
         x,y=st.pop(); cells.append((x,y))
         for dx in (-1,0,1):
          for dy in (-1,0,1):
           nx,ny=x+dx,y+dy
           if 0<=nx<h and 0<=ny<w and grid[nx][ny] and (nx,ny) not in seen:
            seen.add((nx,ny)); st.append((nx,ny))
        rs=[x for x,y in cells]; cs=[y for x,y in cells]
        comps.append((min(rs),max(rs),min(cs),max(cs),cells))
    upper=[x for x in comps if x[0] < h//2]
    lower=[x for x in comps if x[0] >= h//2]
    colors=set(grid[r][c] for x in upper for r,c in x[4])
    if not lower: lower=comps
    best=max(lower,key=lambda x:(len(set(grid[r][c] for r,c in x[4])&colors),-x[0]))
    r0,r1,c0,c1,_=best
    return [row[c0:c1+1] for row in grid[r0:r1+1]]"}

